        /// <para>This overrides the relative system scale and relative speed scale hints. Should be called prior to enabling relative mouse mode, fails otherwise.</para>
        /// </remarks>
        /// <param name="callback">a callback used to transform relative mouse motion, or NULL for default behavior.</param>
        /// <param name="userdata">a pointer that will be passed to <c>callback</c>.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.4.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetRelativeMouseTransform">SDL_SetRelativeMouseTransform</seealso></SDLWiki>
        public static extern void SetRelativeMouseTransform();

        /// <summary>
        /// <para>Set relative mouse mode for a window.</para>
        /// </summary>
        /// <remarks>
        /// <para>While the window has focus and relative mouse mode is enabled, the cursor is hidden, the mouse position is constrained to the window, and SDL will report continuous relative mouse motion even if the mouse is at the edge of the window.</para>
        /// <para>If you'd like to keep the mouse position fixed while in relative mode you can use <see cref="CSDL.Video.Window.MouseRect">MouseRect</see>. If you'd like the cursor to be at a specific location when relative mode ends, you should use <see cref="CSDL.Input.Mouse.WarpInWindow">WarpInWindow</see> before disabling relative mode.</para>
        /// <para>This function will flush any pending mouse motion for this window.</para>
        /// </remarks>
        /// <param name="window">the window to change.</param>
        /// <param name="enabled">true to enable relative mode, false to disable.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_SetWindowRelativeMouseMode">SDL_SetWindowRelativeMouseMode</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Mouse.GetWindowRelativeMode">GetWindowRelativeMode</see></seealso>
        public static extern void SetWindowRelativeMouseMode();

        /// <summary>
        /// <para>Show the cursor.</para>
        /// </summary>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_ShowCursor">SDL_ShowCursor</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Mouse.CursorVisible">CursorVisible</see></seealso>
        /// <seealso><see cref="CSDL.Input.Mouse.HideCursor">HideCursor</see></seealso>
        public static extern void ShowCursor();

        /// <summary>
        /// <para>Move the mouse to the given position in global screen space.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function generates a mouse motion event.</para>
        /// <para>A failure of this function usually means that it is unsupported by a platform.</para>
        /// <para>Note that this function will appear to succeed, but not actually move the mouse when used over Microsoft Remote Desktop.</para>
        /// </remarks>
        /// <param name="x">the x coordinate.</param>
        /// <param name="y">the y coordinate.</param>
        /// <returns>
        /// <para>(bool) Returns true on success or false on failure; call <see cref="CSDL.Error.GetError">GetError</see> for more information.</para>
        /// </returns>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WarpMouseGlobal">SDL_WarpMouseGlobal</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Mouse.WarpInWindow">WarpInWindow</see></seealso>
        public static extern void WarpMouseGlobal();

        /// <summary>
        /// <para>Move the mouse cursor to the given position within the window.</para>
        /// </summary>
        /// <remarks>
        /// <para>This function generates a mouse motion event if relative mode is not enabled. If relative mode is enabled, you can force mouse events for the warp by setting the <see cref="CSDL.Hints.MouseRelativeWarpMotion">MouseRelativeWarpMotion</see> hint.</para>
        /// <para>Note that this function will appear to succeed, but not actually move the mouse when used over Microsoft Remote Desktop.</para>
        /// </remarks>
        /// <param name="window">the window to move the mouse into, or NULL for the current mouse focus.</param>
        /// <param name="x">the x coordinate within the window.</param>
        /// <param name="y">the y coordinate within the window.</param>
        /// <threadsafety>This function should only be called on the main thread.</threadsafety>
        /// <since>This function is available since SDL 3.2.0</since>
        /// <SDLWiki><seealso href="https://wiki.libsdl.org/SDL3/SDL_WarpMouseInWindow">SDL_WarpMouseInWindow</seealso></SDLWiki>
        /// <seealso><see cref="CSDL.Input.Mouse.WarpGlobal">WarpGlobal</see></seealso>
        public static extern void WarpMouseInWindow();
    }
}
